mapper.update:
UPDATE t_economic_fact
SET status = 'SUPERSEDED', update_time = #{now}
WHERE id = #{id} AND status = 'APPROVED' AND fact_version = #{factVersion}

UPDATE t_economic_fact
SET published_at = #{now}, update_time = #{now}
WHERE id = #{id} AND fact_version = #{factVersion} AND status IN ('APPROVED', 'SUPERSEDED') AND published_at IS NULL

mapper.select:
SELECT  FROM t_economic_fact
WHERE  AND status IN ('APPROVED', 'SUPERSEDED') AND id > #{fromFactId}
ORDER BY id
LIMIT #{limit}
